static const char *map_dwarf_reg_to_x86_64_reg(ut64 reg_num, VariableLocationKind *kind) {
	*kind = LOCATION_REGISTER;
	switch (reg_num) {
		case 0: return "rax";
		case 1: return "rdx";
		case 2: return "rcx";
		case 3: return "rbx";
		case 4: return "rsi";
		case 5: return "rdi";
		case 6:
			*kind = LOCATION_BP;
			return "rbp";
		case 7:
			*kind = LOCATION_SP;
			return "rsp";
		case 8: return "r8";
		case 9: return "r9";
		case 10: return "r10";
		case 11: return "r11";
		case 12: return "r12";
		case 13: return "r13";
		case 14: return "r14";
		case 15: return "r15";
		case 17: return "xmm0";
		case 18: return "xmm1";
		case 19: return "xmm2";
		case 20: return "xmm3";
		case 21: return "xmm4";
		case 22: return "xmm5";
		case 23: return "xmm6";
		case 24: return "xmm7";
		default:
			*kind = LOCATION_UNKNOWN;
			return "unsupported_reg";
	}
}

static const char *map_dwarf_reg_to_x86_reg(ut64 reg_num, VariableLocationKind *kind) {
	*kind = LOCATION_REGISTER;
	switch (reg_num) {
		case 0: return "eax";
		case 1: return "edx";
		case 2: return "ecx";
		case 3: return "ebx";
		case 4:
			*kind = LOCATION_SP;
			return "esp";
		case 5:
			*kind = LOCATION_BP;
			return "ebp";
		case 6: return "esi";
		case 7: return "edi";
		case 21: return "xmm0";
		case 22: return "xmm1";
		case 23: return "xmm2";
		case 24: return "xmm3";
		case 25: return "xmm4";
		case 26: return "xmm5";
		case 27: return "xmm6";
		case 28: return "xmm7";
		default:
			r_warn_if_reached ();
			*kind = LOCATION_UNKNOWN;
			return "unsupported_reg";
	}
}

static const char *get_dwarf_reg_name(char *arch, int reg_num, VariableLocationKind *kind, int bits) {
	if (!strcmp (arch, "x86")) {
		if (bits == 64) {
			return map_dwarf_reg_to_x86_64_reg (reg_num, kind);
		} else {
			return map_dwarf_reg_to_x86_reg (reg_num, kind);
		}
	} else if (!strcmp (arch, "ppc")) {
		if (bits == 64) {
			return map_dwarf_reg_to_ppc64_reg (reg_num, kind);
		}
	}
	*kind = LOCATION_UNKNOWN;
	return "unsupported_reg";
}

